const lessons=[{"sentences":[{"speaker":"A","text":"Welcome to our community recycling centre because we want everyone to understand our daily process.","position":1,"audioStartSeconds":0,"audioEndSeconds":6.358083333333333},{"speaker":"A","text":"When you arrive at the main entrance, you must park your vehicle in the gravel zone.","position":2,"audioStartSeconds":6.558083333333333,"audioEndSeconds":11.545958333333333},{"speaker":"A","text":"Before you unload any materials, please stop at the small wooden office to collect a recycling basket.","position":3,"audioStartSeconds":11.745958333333334,"audioEndSeconds":18.253708333333332},{"speaker":"A","text":"Each visitor receives two baskets because we separate plastic items from paper goods immediately.","position":4,"audioStartSeconds":18.453708333333335,"audioEndSeconds":24.728708333333334},{"speaker":"A","text":"Although staff members help you sort heavy objects, you must carry light packaging yourself.","position":5,"audioStartSeconds":24.928708333333333,"audioEndSeconds":30.625375},{"speaker":"A","text":"After you finish sorting everything, you should walk towards the central weighing station.","position":6,"audioStartSeconds":30.825375,"audioEndSeconds":36.05733333333333},{"speaker":"A","text":"Our friendly supervisor records the total weight on a small green ticket before you leave.","position":7,"audioStartSeconds":36.257333333333335,"audioEndSeconds":41.97895833333333},{"speaker":"A","text":"If you collect enough points on your ticket, you can visit our small gift shop.","position":8,"audioStartSeconds":42.178958333333334,"audioEndSeconds":47.101625},{"speaker":"A","text":"The shop sells handmade items that volunteers create from discarded glass bottles and old textiles.","position":9,"audioStartSeconds":47.301625,"audioEndSeconds":53.87379166666667},{"speaker":"A","text":"Visitors usually spend about forty minutes completing this entire educational circuit around our facility.","position":10,"audioStartSeconds":54.073791666666665,"audioEndSeconds":60.968125},{"speaker":"A","text":"Please remember that smoking remains strictly prohibited across the entire outdoor property at all times.","position":11,"audioStartSeconds":61.168125,"audioEndSeconds":67.77820833333334},{"speaker":"A","text":"We hope you enjoy your informative tour and learn valuable habits for protecting our environment.","position":12,"audioStartSeconds":67.97820833333333,"audioEndSeconds":73.89116666666666}],"questions":[{"prompt":"Parking location: ______","answer":"gravel zone","evidenceSentence":2,"evidence":"gravel zone","explanation":"Hướng dẫn viên yêu cầu đỗ xe ở khu vực sỏi ('gravel zone')."},{"prompt":"Office material collected: ______","answer":"recycling basket","evidenceSentence":3,"evidence":"recycling basket","explanation":"Khách tham quan ghé văn phòng nhỏ để lấy một giỏ tái chế ('recycling basket')."},{"prompt":"Number of baskets given: ______","answer":"two","evidenceSentence":4,"evidence":"two","explanation":"Mỗi khách nhận được hai ('two') giỏ để phân loại đồ vật."},{"prompt":"Final station before leaving: ______","answer":"weighing station","evidenceSentence":6,"evidence":"weighing station","explanation":"Sau khi phân loại xong, khách đi về phía trạm cân trung tâm ('weighing station')."},{"prompt":"Ticket color: ______","answer":"green","evidenceSentence":7,"evidence":"green","explanation":"Người giám sát ghi tổng trọng lượng lên một chiếc vé màu xanh lá nhỏ ('green ticket')."},{"prompt":"Total tour duration: ______","answer":"forty minutes","evidenceSentence":10,"evidence":"forty minutes","explanation":"Khách tham quan thường dành khoảng bốn mươi phút ('forty minutes') để hoàn thành chuyến tham quan."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
